        if device == "cuda":
            gpu = torch.cuda.get_device_name(0)
        elif device == "xpu":
            gpu = torch.xpu.get_device_name(0)
        elif device == "npu":
            gpu = torch.npu.get_device_name(0)
        elif device == "mlu":
            gpu = torch.mlu.get_device_name(0)
        else:
            gpu = "other"
